```dart
import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss;

  Transaction(this.coinName, this.dateTime, this.profitLoss);
}

Map<String, List<double>> calculateAverageProfitAndLoss(List<Transaction> transactions) {
  Map<String, List<double>> coinStats = {};

  for (var transaction in transactions) {
    if (coinStats.containsKey(transaction.coinName)) {
      coinStats[transaction.coinName]!.add(transaction.profitLoss);
    } else {
      coinStats[transaction.coinName] = [transaction.profitLoss];
    }
  }

  return coinStats.map((coin, stats) => MapEntry(coin, calculateAverage(stats)));
}

double calculateAverage(List<double> values) {
  return (values.reduce((sum, value) => sum + value) / values.length);
}

List<String> getTopCoins(Map<String, MapEntry<String, double>> coinStats, int numTop, String type) {
  return coinStats.entries.where((entry) => entry.value is Map<String, dynamic> && type == (entry.value['avg'] > 0 ? 'profit' : 'loss'))
      .map((entry) => entry.key)
      .take(numTop)
      .toList();
}

