const axios = require('axios'); // Make sure to install 'axios' package first: npm install axios

function postMessageToSlackChannel(text, channel) {
  const options = {
    method: 'post',
    url: `https://slack.com/api/chat.postMessage`,
    headers: { 'Content-Type': 'application/json' },
    auth: {
      username: process.env.SLACK_BOT_USERNAME,
      password: process.env.SLACK_BOT_TOKEN,
