 Here's an example of how to create an app using Nest.js and TypeORM with professional access permission guards based on user roles and an array of permissions:

```javascript
// Import required packages
const { NestFactory } = require('@nestjs/core');
const typeorm = require('typeorm');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

// Create a new instance of the Nest factory
const app = new NestFactory();

// Define User entity
@Entity()
class User {
  @PrimaryGeneratedColumn() id: number;

  @Column() username: string;

  @Column() password: string;

  @Column() role: string;

  // Add other columns if necessary
}

// Define JWT strategy
const jwtStrategy = (req, callback) => {
  const token = req.headers['authorization'].split(' ')[1];
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    return callback(null, decoded);
  } catch (err) {
    return callback(new UnauthorizedException());
  }
};

// Define Auth guard
@Injectable()
class AuthGuard {
  canActivate(context) {
    const request = context.switchToHttp().getRequest();
    return new Promise((resolve, reject) => {
      request.user = this.authenticate(request);
      if (!request.user) {
        reject(new UnauthorizedException());
      }
      resolve();
    });
  }

  authenticate(request) {
    const token = request.headers['authorization']?.split(' ')[1];
    if (!token) {
      return null;
    }

    try {
      const decoded = jwt.verify(token, process.env.JWT_SECRET);
      return { userId: decoded.userId, role: decoded.role };
    } catch (err) {
      return null;
    }
  }
