 I'd be happy to help you write an Apps Script function that searches for a place name using the Google Maps Geocoding API and stores the latitude and longitude in separate columns of a Google Spreadsheet. Here's an example of how you might implement this:

```javascript
function geocodePlaces(sheetName) {
  // Replace "Sheet1" with the name of your sheet
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  const columnAStart = 1; // Column A is the first column (index 1)
  const columnBStart = 2; // Column B is the second column (index 2)
  const columnCStart = 3; // Column C is the third column (index 3)

  // Get the number of rows in the sheet
  const numRows = sheet.getLastRow();

  for (let i = 1; i <= numRows; i++) {
    const placeName = sheet.getRange(i, columnAStart).getValue();

    if (!placeName) continue; // Skip empty cells

    const apiKey = 'YOUR_API_KEY'; // Replace with your own Google Maps API key
    const url = `https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(placeName)}&key=${apiKey}`;

    try {
      const response = UrlFetchApp.fetch(url);
      const json = JSON.parse(response.getContentText());

      if (json.status === 'OK') {
        const location = json.results[0].geometry.location;
        sheet.getRange(i, columnBStart).setValue(location.lng);
        sheet.getRange(i, columnCStart).setValue(location.lat);
      }
    } catch (e) {
      Logger.log(`Error geocoding "${placeName}": ${e}`);
    }
  }
}
```

