function Wrapper() {
  return (
    <AuthProvider
      domain="<your-domain>.auth0.com"
      clientID="<your-client-id>"
      redirectUri={window.location.origin}
    >
      <App />
    </AuthProvider>
  );
}

export default Wrapper;
```

Replace `<your-domain>` and `<your-client-id>` with your Auth0 domain and client ID respectively.

**Step 3: Configure Second React App**
Install the same dependencies in your second React app and create a new file `AuthWrapper.js`:

```javascript
// In AuthWrapper.js
import { useAuth } from '@auth0/auth0-react';
import React from 'react';
import App from './App';

function AuthWrapper() {
  const { isAuthenticated, loginWithRedirect, logout } = useAuth();

  if (!isAuthenticated) loginWithRedirect({ screen_hint: 'signup' });

  return <App />;
}

export default AuthWrapper;
```

