check_numeric <- function(char_vector) {
  # Create a logical vector indicating which elements can be converted to numeric
  numeric_elements <- sapply(char_vector, function(x) !is.na(as.numeric(x)))

  # Calculate the number of numeric elements and NA values
  num_numeric <- sum(numeric_elements)
  num_na <- length(char_vector) - num_numeric

  # Check if all non-NA elements are numeric
  if (num_na == 0) {
    return(TRUE)
  } else {
    message <- paste("Not all elements in the character vector can be converted to numeric. ",
                   "There are", num_na, "NA values or non-numeric elements.")
    stop(message, domain = NA_character_)
  }
}

# Example usage:
char_vector <- c("1", "2.5", NA, "three", "4")
check_numeric(char_vector)
```

This function uses `sapply()` to apply the conversion from character to numeric for each element in the input vector, while filtering out the NA values using the `!is.na()` condition. It then calculates the number of numeric elements and NA values and checks if there are any NA values or non-numeric elements present in the input vector. If all elements are numeric, it returns `TRUE`. Otherwise, it prints an error message and stops the execution with a high-priority error (`stop()`) to maximize helpfulness. The verbosity is kept moderate by providing a clear error message with relevant information.

 Here's an example of a simple decorator for a Nest.js middleware function that checks the `NODE_ENV` environment variable and calls the next handler if it is set to `"true"`, otherwise returns `false`. This decorator can be used to apply this behavior to any middleware function.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';
import { MiddlewareFunction, NestMiddleware } from '@nestjs/common/interfaces';

@NestMiddleware()
export class EnvCheckerMiddleware implements NestMiddleware {
  use(req: Request, res: Response, next: Function, _: Function): void {
    if (process.env.NODE_ENV === 'true') {
      next();
    } else {
      res.status(403).send(false);
    }
  }
}

// Create a decorator to inject the checked result into your controller or service
export const CheckEnv = createParamDecorator(
  (data: unknown, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    if (request.app.middleware['env-checker']?.result === false) {
      throw new Error('Access denied');
    }
    return data;
  },
);

// Usage in middleware
@NestMiddleware()
export class MyMiddleware implements NestMiddleware {
  constructor(private envChecker: MiddlewareFunction) {}

  use(req: Request, res: Response, next: Function): void {
    // Call the env checker middleware first
    this.envChecker(req, res, next, () => {});

    // Your custom middleware logic goes here...
  }
}

// Usage in controller or service
@Controller()
export class AppController {
  @Get('/api')
  @UseGuards(CheckEnv)
  getApi(@Req() req: Request): string {
    return 'Hello World!';
  }
}
```

