CREATE PROCEDURE ConvertTemperature
   @Celsius DECIMAL(5,2),
   @Fahrenheit DECIMAL(6,2) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    -- Input validation
    IF (@Celsius IS NULL)
    BEGIN
        RAISERROR ('Celsius value is required.', 16, 1);
        RETURN;
    END;

    -- Conversion formula
    SET @Fahrenheit = (CAST(@Celsius AS FLOAT) * 1.8) + 32;

    -- Error handling
