 Here's an example implementation of the `RedisClient` class in Node.js using the `redis` package:

```javascript
const redis = require('redis');

class RedisClient {
  constructor() {
    this.client = new redis();
    this.client.on('error', (err) => {
      console.error('Error connecting to Redis:', err);
    });
  }

  isAlive() {
    return this.client.connected;
  }

  async get(key) {
    return new Promise((resolve, reject) => {
      this.client.get(key, (err, value) => {
        if (err) {
          reject(err);
        } else {
          resolve(value);
        }
      });
    });
  }

  async set(key, value, duration) {
    return new Promise((resolve, reject) => {
      this.client.set(key, value, 'EX', duration, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }

  async del(key) {
    return new Promise((resolve, reject) => {
      this.client.del(key, (err, reply) => {
        if (err) {
          reject(err);
        } else {
          resolve(reply);
        }
      });
    });
  }
}

const redisClient = new RedisClient();
module.exports = redisClient;
```

This implementation initializes a new `redis` client when the `RedisClient` constructor is called. It sets up an error event listener for the client to display any errors in the console. The `isAlive` method checks whether the client is connected to Redis or not. The `get`, `set`, and `del` methods are asynchronous functions that make use of Promises to handle the callback-based API of the `redis` package. Finally, an instance of the `RedisClient` is created and exported from the module.

